<script setup lang="ts">import{companies}from'../stores/career';import briefs from'../data/industries.json';const slug=(x:string)=>encodeURIComponent(x);const groups=Object.entries(companies.reduce((o,c)=>{o[c.industry]=(o[c.industry]||0)+1;return o},{} as Record<string,number>)).sort((a,b)=>b[1]-a[1]);</script>
<template><main><div class="eyebrow">24 CAREER FIELDS</div><h1>行业探索</h1><p class="lede">先理解每个领域有多少目标公司，再决定公司和岗位。</p><div class="industry-grid"><RouterLink v-for="[name,count] in groups" :key="name" :to="`/industries/${slug(name)}`" class="card industry"><strong>{{name}}</strong><span>{{count}} 家公司</span><p>{{(briefs as Record<string,string>)[name]||'查看该领域的公司、岗位和推荐原因。'}}</p></RouterLink></div></main></template>
